183→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
184→    void SendAcknowledgeUsda();
185→
186→    /** Send answer via USD (v2.0.0) */
187→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
188→    void SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs);
189→
190→    // === CONFIGURATION ===
191→
