201→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge")
202→    float DebounceTime = 0.05f;
203→
204→private:
205→    // === FILE WATCHING ===
206→
207→    void SetupFileWatcher();
208→    void TeardownFileWatcher();
