210→#if WITH_DIRECTORY_WATCHER
211→    void OnDirectoryChanged(const TArray<FFileChangeData>& Changes);
212→#endif
213→
214→    // === STATE HANDLING ===
215→
216→    void ProcessStateFile();
217→    void HandleReadyState(const TSharedPtr<FJsonObject>& JsonObj);
218→    void HandleQuestionState(const TSharedPtr<FJsonObject>& JsonObj);
219→    void HandleTransitionState(const TSharedPtr<FJsonObject>& JsonObj);
220→    void HandleFinaleState(const TSharedPtr<FJsonObject>& JsonObj);
221→
222→    // === USD NATIVE COMMUNICATION (v2.0.0) ===
223→
224→    bool ProcessBridgeStateUsda();
225→    FString ParseUsdaVariant(const FString& Content, const FString& VariantSetName);
226→    FString ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName);
227→    void HandleUsdaReadyState(const FString& Content);
228→    void HandleUsdaQuestionState(const FString& Content);
229→    void HandleUsdaTransitionState(const FString& Content);
230→    void HandleUsdaFinaleState(const FString& Content);
231→    FString BuildQuestionJson();
232→    FString UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue);
233→    FString UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString);
234→    void UpdateBehavioralSignals(FString& Content, float ResponseTimeMs);
