  92→void UBridgeComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
  93→{
  94→    TeardownFileWatcher();
  95→
  96→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT STOPPED"));
  97→
  98→    Super::EndPlay(EndPlayReason);
  99→}
