 193→
 194→void UBridgeComponent::TeardownFileWatcher()
 195→{
 196→#if WITH_DIRECTORY_WATCHER
 197→    if (WatchHandle.IsValid())
 198→    {
 199→        FDirectoryWatcherModule& DirWatcherModule =
 200→            FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
 201→        IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
 202→
 203→        if (DirWatcher)
 204→        {
 205→            DirWatcher->UnregisterDirectoryChangedCallback_Handle(BridgePath, WatchHandle);
 206→            BridgeLog(TEXT("File watcher unregistered"));
 207→        }
 208→    }
 209→#endif
 210→}
