 244→// === STATE HANDLING ===
 245→
 246→void UBridgeComponent::ProcessStateFile()
 247→{
 248→    // Try USD mode first (v2.0.0)
 249→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 250→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 251→
 252→    if (PlatformFile.FileExists(*UsdFilePath))
 253→    {
 254→        if (ProcessBridgeStateUsda())
 255→        {
 256→            return; // Successfully processed USD
 257→        }
 258→    }
 259→
 260→    // Fall back to JSON mode (v1.0.0)
 261→    FString FilePath = GetBridgeFilePath(TEXT("state.json"));
 262→    FString Content;
 263→
 264→    BridgeLog(FString::Printf(TEXT("Attempting to read: %s"), *FilePath));
 265→
 266→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 267→    {
 268→        BridgeLog(FString::Printf(TEXT("FAILED to read: %s (exists: %d)"),
 269→            *FilePath, PlatformFile.FileExists(*FilePath) ? 1 : 0));
 270→        return;
 271→    }
 272→
 273→    // Parse JSON
 274→    TSharedPtr<FJsonObject> JsonObj;
 275→    TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Content);
 276→
 277→    if (!FJsonSerializer::Deserialize(Reader, JsonObj) || !JsonObj.IsValid())
 278→    {
 279→        BridgeLog(TEXT("ERROR: Invalid JSON in state.json"));
 280→        return;
 281→    }
 282→
 283→    CurrentStateJson = Content;
 284→    bUsingUsdMode = false;
 285→
 286→    // Route by type
 287→    FString StateType;
 288→    if (JsonObj->TryGetStringField(TEXT("type"), StateType))
 289→    {
 290→        if (StateType == TEXT("ready"))
 291→        {
 292→            HandleReadyState(JsonObj);
 293→        }
 294→        else if (StateType == TEXT("question"))
 295→        {
 296→            HandleQuestionState(JsonObj);
 297→        }
 298→        else if (StateType == TEXT("transition"))
 299→        {
 300→            HandleTransitionState(JsonObj);
 301→        }
 302→        else if (StateType == TEXT("finale"))
 303→        {
 304→            HandleFinaleState(JsonObj);
 305→        }
 306→        else
 307→        {
 308→            BridgeLog(FString::Printf(TEXT("Unknown state type: %s"), *StateType));
 309→        }
 310→    }
 311→}
