 573→FString UBridgeComponent::ParseUsdaVariant(const FString& Content, const FString& VariantSetName)
 574→{
 575→    // Parse variant selection from: variants = { string variantName = "value" }
 576→    FString Pattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *VariantSetName);
 577→    FRegexPattern RegexPattern(Pattern);
 578→    FRegexMatcher Matcher(RegexPattern, Content);
 579→
 580→    if (Matcher.FindNext())
 581→    {
 582→        return Matcher.GetCaptureGroup(1);
 583→    }
 584→    return TEXT("");
 585→}
 586→
 587→
 588→FString UBridgeComponent::ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName)
 589→{
 590→    // Find the prim section and extract attribute value
 591→    // This is a simplified parser - handles basic string/int/float attributes
 592→
 593→    // First find the prim section
 594→    FString PrimPattern = FString::Printf(TEXT("def [^\"]*\"%s\"[^{]*\\{([^}]*)\\}"), *PrimPath);
 595→    FRegexPattern PrimRegex(PrimPattern);
 596→    FRegexMatcher PrimMatcher(PrimRegex, Content);
 597→
 598→    FString PrimContent;
 599→    if (PrimMatcher.FindNext())
 600→    {
 601→        PrimContent = PrimMatcher.GetCaptureGroup(1);
 602→    }
 603→    else
 604→    {
 605→        // Try finding nested prim
 606→        PrimContent = Content;
 607→    }
 608→
 609→    // Parse string attribute
 610→    FString StringPattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *AttrName);
 611→    FRegexPattern StringRegex(StringPattern);
 612→    FRegexMatcher StringMatcher(StringRegex, PrimContent);
 613→    if (StringMatcher.FindNext())
 614→    {
 615→        return StringMatcher.GetCaptureGroup(1);
 616→    }
 617→
 618→    // Parse int attribute
 619→    FString IntPattern = FString::Printf(TEXT("int %s = (-?\\d+)"), *AttrName);
 620→    FRegexPattern IntRegex(IntPattern);
 621→    FRegexMatcher IntMatcher(IntRegex, PrimContent);
 622→    if (IntMatcher.FindNext())
 623→    {
 624→        return IntMatcher.GetCaptureGroup(1);
 625→    }
 626→
 627→    // Parse float/double attribute
 628→    FString FloatPattern = FString::Printf(TEXT("(?:float|double) %s = ([\\d.]+)"), *AttrName);
 629→    FRegexPattern FloatRegex(FloatPattern);
 630→    FRegexMatcher FloatMatcher(FloatRegex, PrimContent);
 631→    if (FloatMatcher.FindNext())
 632→    {
 633→        return FloatMatcher.GetCaptureGroup(1);
 634→    }
 635→
 636→    return TEXT("");
 637→}
