 655→void UBridgeComponent::HandleUsdaQuestionState(const FString& Content)
 656→{
 657→    // Parse Message prim
 658→    CurrentQuestion = FTranslatorsQuestion();
 659→    CurrentQuestion.Index = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("index")));
 660→    CurrentQuestion.Total = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Message"), TEXT("total")));
 661→    CurrentQuestion.QuestionId = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("question_id"));
 662→    CurrentQuestion.Text = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("text"));
 663→    CurrentQuestion.Scene = ParseUsdaAttribute(Content, TEXT("Message"), TEXT("scene"));
 664→
 665→    // Parse Options
 666→    for (int32 i = 0; i < 3; ++i)
 667→    {
 668→        FString OptionPrim = FString::Printf(TEXT("Option_%d"), i);
 669→        FString Label = ParseUsdaAttribute(Content, OptionPrim, TEXT("label"));
 670→        FString Direction = ParseUsdaAttribute(Content, OptionPrim, TEXT("direction"));
 671→
 672→        if (!Label.IsEmpty())
 673→        {
 674→            CurrentQuestion.OptionLabels.Add(Label);
 675→            CurrentQuestion.OptionDirections.Add(Direction);
 676→        }
 677→    }
 678→
 679→    // Assign depth label based on question index
 680→    CurrentQuestion.DepthLabel = GetDepthLabelForIndex(CurrentQuestion.Index);
 681→
 682→    BridgeLog(FString::Printf(TEXT("USD Question %d/%d [%s]: %s"),
 683→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.DepthLabel, *CurrentQuestion.QuestionId));
 684→
 685→    // Build JSON for backward-compatible delegate
 686→    CurrentStateJson = BuildQuestionJson();
 687→    OnQuestionReceived.Broadcast(CurrentStateJson);
 688→}
