 746→void UBridgeComponent::SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs)
 747→{
 748→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 749→    FString Content;
 750→
 751→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 752→    {
 753→        BridgeLog(TEXT("ERROR: Could not read bridge_state.usda for answer"));
 754→        // Fall back to JSON
 755→        SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 756→        return;
 757→    }
 758→
 759→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
 760→    FString SelectedLabel = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionLabels.Num())
 761→        ? CurrentQuestion.OptionLabels[OptionIndex] : TEXT("");
 762→    FString SelectedDirection = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionDirections.Num())
 763→        ? CurrentQuestion.OptionDirections[OptionIndex] : TEXT("");
 764→
 765→    // Update sync_status variant to "answer_received"
 766→    Content = UpdateUsdaVariant(Content, TEXT("sync_status"), TEXT("answer_received"));
 767→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("answer"));
 768→
 769→    // Update Answer prim attributes
 770→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("question_id"), QuestionId, true);
 771→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("option_index"), FString::FromInt(OptionIndex), false);
 772→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 773→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_label"), SelectedLabel, true);
 774→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_direction"), SelectedDirection, true);
 775→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("timestamp"), Timestamp, true);
 776→
 777→    // Update behavioral signals
 778→    UpdateBehavioralSignals(Content, ResponseTimeMs);
 779→
 780→    // Write back
 781→    int32 MaxRetries = 3;
 782→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 783→    {
 784→        if (FFileHelper::SaveStringToFile(Content, *FilePath))
 785→        {
 786→            BridgeLog(FString::Printf(TEXT("USD answer sent: %s = option %d (%.0fms)"),
 787→                *QuestionId, OptionIndex, ResponseTimeMs));
 788→            return;
 789→        }
 790→        FPlatformProcess::Sleep(0.1f);
 791→    }
 792→
 793→    BridgeLog(TEXT("ERROR: Failed to write USD answer, falling back to JSON"));
 794→    SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 795→}
