 798→FString UBridgeComponent::UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue)
 799→{
 800→    // Simple string replacement for variant - more reliable than regex
 801→    FString SearchPattern = FString::Printf(TEXT("string %s = \""), *VariantSetName);
 802→    int32 StartIdx = Content.Find(SearchPattern);
 803→    if (StartIdx == INDEX_NONE)
 804→    {
 805→        return Content;
 806→    }
 807→
 808→    StartIdx += SearchPattern.Len();
 809→    int32 EndIdx = Content.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 810→    if (EndIdx == INDEX_NONE)
 811→    {
 812→        return Content;
 813→    }
 814→
 815→    // Build new content
 816→    FString Result = Content.Left(StartIdx) + NewValue + Content.Mid(EndIdx);
 817→    return Result;
 818→}
