1208→        }
1209→        else if (Trait.Score <= 0.3f)
1210→        {
1211→            Trait.Behavior = FString::Printf(TEXT("Measured %s approach"), *Trait.Label);
1212→        }
1213→        else
1214→        {
1215→            Trait.Behavior = FString::Printf(TEXT("Balanced %s style"), *Trait.Label);
1216→        }
1217→
